  + name : string
}

Home "1" *-- "*" Department
Department "1" *-- "*" Room
Room "1" *-- "*" Bed
Bed "*" -- "1" Category
Inhabitant "1" *-- "*" Stay
Stay "*" -- "1" StayType
Stay "1" -- "1" Bed
Inhabitant "1" -- "0..1" Representative
Inhabitant "1" -- "1" Registration
Registration "1" -- "1" Assessment
Assessment "1" -- "1" StayType
StayType "1" -- "*" WaitingList
WaitingList "*" -- "1" Inhabitant
Stay "1" -- "*" Invoice
Invoice "1" -- "1" PaymentEvent
Invoice "1" -- "0..1" CreditNote

@enduml

